    read(addr) {
      if (addr < 0x2000) return ram[addr & 0x7FF];
      if (addr >= A.base && addr < A.base + rom.length) return rom[addr - A.base];
      if (addr === 0x4015) return 0;
      S.badReads++; return 0;
    },
    write(addr, v) {
      if (addr < 0x2000) ram[addr & 0x7FF] = v;
      else if (addr >= 0x4000 && addr <= 0x4017) writes.push(addr, v);
    }
